SELECT pr.code, COUNT(*) AS uses FROM orders o JOIN promotions pr ON pr.promo_id = o.promo_id WHERE NOT o.is_deleted AND o.status NOT IN ('cancelled', 'canceled', 'payment_failed') AND CAST(o.order_at AS DATE) BETWEEN DATE '2026-04-01' AND DATE '2026-06-30' GROUP BY pr.code ORDER BY uses DESC, pr.code LIMIT 5
